25	/// A RAII guard that holds a shared read lock over the workers list and exposes
26	/// a reference to a single [`WorkspaceWorker`] inside it.
27	///
28	/// Obtained from [`WorkerManager::get_worker_for_uri`].
29	/// The read lock is held for as long as this guard is alive.
30	pub struct WorkerGuard<'a> {
31	    guard: WorkerGuardInner<'a>,
32	    index: usize,
33	}
34	
35	impl std::ops::Deref for WorkerGuard<'_> {
36	    type Target = WorkspaceWorker;
37	
38	    fn deref(&self) -> &Self::Target {
39	        match &self.guard {
40	            WorkerGuardInner::Vec(vec_guard) => &vec_guard[self.index],
41	            #[cfg(test)]
42	            WorkerGuardInner::Single(single_guard) => single_guard,
43	        }
44	    }
45	}
