53	    // the manager works in 2 modes, when no workspaces are configured, it creates workers dynamically for file URIs.
54	    // When workspaces are reconfigured (added or removed by the client), it creates workers for those and ignores file URIs outside of them.
55	    DynamicNoWorkspaces(
