65	/// Manages the lifecycle of [`WorkspaceWorker`]s for the language server.
66	///
67	/// Responsibilities:
68	/// - Storing and providing access to all active workers (one per workspace root).
69	/// - Tracking whether the server is in *single-file mode* (no workspace folders
70	///   were provided during `initialize`).
71	/// - Creating workers via the stored [`ToolBuilder`]s so callers do not need
72	///   direct access to those builders.
73	/// - Finding the most-specific worker for any given file URI.
74	/// - Dynamically creating / tearing down workers in single-file mode.
75	/// - Handling workspace-folder additions and removals atomically.
76	///
77	/// **Workers are never cloned** – they are expensive and each root URI must
78	/// have at most one live worker at any point in time.
79	pub struct WorkerManager {
80	    workers: RwLock<Vec<WorkspaceWorker>>,
81	    mode: ManagerMode,
82	    tool_builder: Arc<dyn ToolBuilder>,
83	}
