112	    /// Shut down all workers and clear the worker list.
113	    /// Returns the URIs for which diagnostics should be cleared.
114	    pub async fn stop_manager(&self) -> Vec<Uri> {
115	        let mut clear_uris = vec![];
116	        let workers = {
117	            let mut workers = self.workers.write().await;
118	            std::mem::take(&mut *workers)
119	        };
120	        for worker in workers {
121	            // shutdown each worker and collect the URIs to clear diagnostics.
122	            // unregistering file watchers is not necessary, because the client will do it automatically on shutdown.
123	            // some clients (`helix`) do not expect any requests after shutdown is sent.
124	            let (worker_uris, _) = worker.shutdown().await;
125	            clear_uris.extend(worker_uris);
126	        }
127	
128	        #[cfg(test)]
129	        if let ManagerMode::DynamicWithWorkspaces(worker) = &self.mode {
130	            let (worker_uris, _) = worker.read().await.shutdown().await;
131	            clear_uris.extend(worker_uris);
132	        }
133	
134	        clear_uris
135	    }
