186	    /// It registers dynamic capabilities like file watchers and formatting if the client supports it.
187	    /// It also starts the [WorkspaceWorker]s if they did not start during initialization.
188	    /// If the client supports `workspace/configuration` request, it will request the configuration for each workspace folder
189	    /// and start the [WorkspaceWorker]s with the received configuration.
190	    ///
191	    /// See: <https://microsoft.github.io/language-server-protocol/specifications/specification-current/#initialized>
192	    async fn initialized(&self, _params: InitializedParams) {
193	        debug!("oxc initialized.");
194	        let Some(capabilities) = self.capabilities.get() else {
195	            return;
196	        };
197	
198	        let workspace_workers = &*self.worker_manager.read_workspace_workers().await;
199	        let needed_configurations =
200	            ConcurrentHashMap::with_capacity_and_hasher(workspace_workers.len(), FxBuildHasher);
201	        let needed_configurations = needed_configurations.pin_owned();
202	        for worker in workspace_workers {
203	            if worker.needs_init_options().await {
204	                needed_configurations.insert(worker.get_root_uri().clone(), worker);
205	            }
206	        }
207	
208	        if !needed_configurations.is_empty() {
209	            let configurations = if capabilities.workspace_configuration {
210	                self.request_workspace_configuration(needed_configurations.keys().collect()).await
211	            } else {
212	                // every worker should be initialized already in `initialize` request
213	                vec![serde_json::Value::Null; needed_configurations.len()]
214	            };
215	
216	            // All open-file URIs
217	            let known_uris = self.file_system.keys();
218	            // will only be filled when using push diagnostic model
219	            let mut new_diagnostics = Vec::new();
220	
221	            for (index, worker) in needed_configurations.values().copied().enumerate() {
222	                // get the configuration from the response and start the worker
223	                let configuration = configurations.get(index).unwrap_or(&serde_json::Value::Null);
224	                debug!("starting worker in initialize with options: {configuration:?}");
225	                worker.start_worker(configuration.clone()).await;
226	
227	                // run diagnostics for all known files in the workspace of the worker.
228	                // This is necessary because the worker was not started before.
229	                // On Pull diagnostic model, we will ask the client to refresh diagnostics instead of sending them all.
230	                if capabilities.diagnostic_mode != DiagnosticMode::Push {
231	                    continue;
232	                }
233	
234	                for uri in &known_uris {
235	                    // Check if this worker is the most specific one for this URI
236	                    let Some(worker) = self.worker_manager.get_worker_for_uri(uri).await else {
237	                        continue;
238	                    };
239	                    let document = self.file_system.get_document(uri);
240	                    let diagnostics = worker.run_diagnostic(&document).await;
241	                    match diagnostics {
242	                        Err(err) => {
