+            let len =
+                header.strip_prefix("Content-Length: ").unwrap().strip_suffix("\r\n\r\n").unwrap();
+            let len: usize = len.parse().unwrap();
+            let (body, rest) = body.split_at(len);
+            ret.push(body.to_string());
